function bloodPlan({weight,volumePerKg=60,reductionPercent=15,dayPercent=1,fortnightPercent=10}) {
  const inputs=[weight,volumePerKg,reductionPercent,dayPercent,fortnightPercent];
  if(!inputs.every(Number.isFinite)||weight<=0||volumePerKg<=0||reductionPercent<0||reductionPercent>=100||dayPercent<0||dayPercent>100||fortnightPercent<0||fortnightPercent>100)throw Error('Use positive weight and blood-volume estimate, reduction below 100%, and valid collection percentages.');
  const baseline=weight*volumePerKg,estimated=baseline*(1-reductionPercent/100);
  const r={baseline,estimated,day:estimated*dayPercent/100,fortnight:estimated*fortnightPercent/100};
  if(!Object.values(r).every(Number.isFinite))throw Error('Inputs exceed the supported range.');
  return r;
}
const bloodFormat=n=>n.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
const escapeBlood=text=>String(text??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function cageSheetMarkup(p,r){
  const field=(value,unit='')=>value!==''&&value!==null&&value!==undefined?escapeBlood(value)+unit:'<span class="blank">&nbsp;</span>'+unit;
  const amount=n=>r?bloodFormat(n)+' mL':'________ mL';
  const rows=Array.from({length:16},()=>'<tr><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr>').join('');
  return `<article class="cage-sheet"><h1>BLOOD COLLECTION LOG</h1><p class="sheet-subtitle">Cage-side record · record blood removed, including discarded blood</p>
  <div class="identity"><div><b>Patient:</b> ${field(p.patient)}</div><div><b>Record / cage:</b> ${field(p.record)}</div><div><b>Species:</b> ${field(p.species)}</div><div><b>Weight:</b> ${field(p.weight,' kg')}</div><div><b>Sheet start:</b> ${field(p.start)}</div><div><b>Clinician:</b> ${field(p.clinician)}</div></div>
  <div class="sheet-guides"><div>ESTIMATED BLOOD VOLUME<strong>${amount(r?.estimated)}</strong></div><div>WORKBOOK 24-HOUR GUIDE<strong>${amount(r?.day)}</strong></div><div>WORKBOOK 14-DAY GUIDE<strong>${amount(r?.fortnight)}</strong></div></div>
  <p class="sheet-method">${r?`Method: ${escapeBlood(p.volumePerKg)} mL/kg × ${escapeBlood(p.weight)} kg, reduced ${escapeBlood(p.reductionPercent)}%; collection guides ${escapeBlood(p.dayPercent)}% per 24 hr and ${escapeBlood(p.fortnightPercent)}% per 14 days.`:'Method / assumptions: __________________________________________________________________'} Workbook estimates are not universal patient-specific limits.</p>
  <div class="approval"><b>Clinician-approved plan:</b> ${field(p.approvedDay,' mL / 24 hr')} &nbsp; ${field(p.approvedFortnight,' mL / 14 days')} &nbsp; <b>Initials:</b> ______</div>
  <p class="carry"><b>Prior removal carried forward:</b> last 24 hr ______ mL &nbsp; last 14 days ______ mL</p>
  <table><colgroup><col style="width:10%"><col style="width:10%"><col style="width:15%"><col style="width:15%"><col style="width:14%"><col style="width:27%"><col style="width:9%"></colgroup><thead><tr><th>Date</th><th>Time</th><th>Blood removed<br>(mL)*</th><th>Sheet running<br>total (mL)</th><th>Draw site</th><th>Test / reason</th><th>Initials</th></tr></thead><tbody>${rows}</tbody></table>
  <div class="sheet-bottom"><p><b>Sheet total:</b> ______ mL &nbsp; <b>Rolling 24-hour total:</b> ______ mL &nbsp; <b>Rolling 14-day total:</b> ______ mL</p><p>*Include discarded blood; do not count saline flush as blood. Rolling totals must include prior draws and other sheets. Both time windows apply; printing a new sheet does not reset the allowance.</p><p><b>Notes / changes to plan:</b> __________________________________________________________________<br>__________________________________________________________________________________________</p><p class="sheet-source">Source method: Fluids Calculator workbook, Fluids!L44:U54. Individualize for the patient and follow the clinician-approved plan. This sheet is a manual log; totals are not tracked automatically.</p></div></article>`;
}
const cageSheetCSS=`@page{size:letter portrait;margin:.4in}*{box-sizing:border-box}body{font:10px/1.35 Arial,sans-serif;color:#000;background:#fff;margin:0}.cage-sheet{max-width:7.7in;margin:auto}h1{font-size:22px;letter-spacing:1px;margin:0 0 3px}.sheet-subtitle{margin:0 0 12px}.identity{display:grid;grid-template-columns:1fr 1fr;gap:9px 20px;margin-bottom:14px}.identity>div{min-height:19px;overflow-wrap:anywhere}.blank{display:inline-block;border-bottom:1px solid #000;min-width:95px}.sheet-guides{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.sheet-guides>div{border:1.5px solid #000;padding:8px;font-size:9px}.sheet-guides strong{display:block;font-size:19px;margin-top:6px}.sheet-method{font-size:8px;margin:7px 0 10px}.approval{border:1.5px solid #000;padding:10px 8px;line-height:1.8}.carry{margin:10px 0}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{border:1px solid #333;text-align:left;padding:4px}th{font-size:9px;height:30px}td{height:24px}.sheet-bottom{font-size:9px}.sheet-bottom p{margin:9px 0}.sheet-source{font-size:8px}.print-toolbar{max-width:7.7in;margin:14px auto;padding:12px;border:1px solid #999;font:14px Arial}.print-toolbar button{padding:9px 15px;font:14px Arial}.print-toolbar p{margin:7px 0 0}@media print{.print-toolbar{display:none}body{margin:0}.cage-sheet{max-width:none}table,thead,tr,.sheet-guides,.approval{break-inside:avoid}thead{display:table-header-group}}`;
function cageSheetDocument(p,r){return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Blood Collection Cage Sheet</title><style>'+cageSheetCSS+'</style></head><body><div class="print-toolbar"><button onclick="window.print()">Print / Save as PDF</button><p>Use Letter portrait, 100% scale, and turn browser headers/footers off. The draw rows are intentionally blank for handwriting.</p></div>'+cageSheetMarkup(p,r)+'</body></html>';}
function bloodCSV(p,r){
  const cell=v=>{let s=String(v??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};
  const lines=[['Blood Collection Log'],['Patient',p.patient],['Record / cage',p.record],['Species',p.species],['Weight (kg)',p.weight],['Sheet start',p.start],['Clinician',p.clinician],['Estimated blood volume (mL)',r.estimated],['Workbook 24-hour guide (mL)',r.day],['Workbook 14-day guide (mL)',r.fortnight],['Clinician-approved mL / 24 hr',p.approvedDay],['Clinician-approved mL / 14 days',p.approvedFortnight],['Blood-volume estimate (mL/kg)',p.volumePerKg],['Reduction (%)',p.reductionPercent],['24-hour collection fraction (%)',p.dayPercent],['14-day collection fraction (%)',p.fortnightPercent],[],['Date','Time','Blood removed incl. discard (mL)','Sheet running total (mL)','Draw site','Test / reason','Initials'],...Array.from({length:16},()=>Array(7).fill(''))];
  return '\uFEFF'+lines.map(row=>row.map(cell).join(',')).join('\r\n');
}
if(typeof module!=='undefined')module.exports={bloodPlan,cageSheetMarkup,cageSheetDocument,bloodCSV};
